-- Enforced for new and updated rows right away. Existing rows are checked by 0008, after they are fixed up.
-- Both constraints are added NOT VALID, so no table scan happens under the strong lock. The short
-- lock_timeout keeps a long-running query from queueing writes behind this statement.
SET LOCAL lock_timeout = '5s';
ALTER TABLE orders ADD CONSTRAINT orders_customer_id_fk
  FOREIGN KEY (customer_id) REFERENCES customers (id) NOT VALID;
ALTER TABLE orders ADD CONSTRAINT orders_total_cents_nonnegative
  CHECK (total_cents >= 0) NOT VALID;

