-- migrate:no-transaction
-- Re-points orders from the 2019 import whose customer no longer exists at the placeholder customer
-- from 0004. Runs in batches by primary key; each batch commits on its own, so row locks are held
-- only briefly and the job can be rerun safely (already-fixed rows no longer match).
SET lock_timeout = '5s';
DO $$
DECLARE
  placeholder_id bigint;
  chunk constant bigint := 10000;
  lower_key bigint := 0;
  max_key bigint;
  moved bigint;
  total bigint := 0;
BEGIN
  SELECT id INTO placeholder_id FROM customers
  WHERE lower(email) = 'deleted-customer@internal.invalid';
  IF placeholder_id IS NULL THEN
    RAISE EXCEPTION 'placeholder customer deleted-customer@internal.invalid is missing (see 0004)';
  END IF;

  SELECT coalesce(max(id), 0) INTO max_key FROM orders;
  WHILE lower_key <= max_key LOOP
    UPDATE orders o SET customer_id = placeholder_id
    WHERE o.id >= lower_key AND o.id < lower_key + chunk
      AND NOT EXISTS (SELECT 1 FROM customers c WHERE c.id = o.customer_id);
    GET DIAGNOSTICS moved = ROW_COUNT;
    total := total + moved;
    lower_key := lower_key + chunk;
    COMMIT;
  END LOOP;
  RAISE NOTICE 'reassigned % orphaned orders to the deleted-customer placeholder', total;
END
$$;
RESET lock_timeout;

